import{_ as l,o as e,c as t,a2 as i}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"安装 Ollama","description":"","frontmatter":{"head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"安装 Ollama · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra user guides — AI roleplay, character cards, BYOK and local models."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ollama/install"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ollama/install"}]]},"headers":[],"relativePath":"ollama/install.md","filePath":"ollama/install.md","lastUpdated":1786085506000}'),s={name:"ollama/install.md"};function n(o,a,r,p,h,d){return e(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="安装-ollama" tabindex="-1">安装 Ollama <a class="header-anchor" href="#安装-ollama" aria-label="Permalink to &quot;安装 Ollama&quot;">​</a></h1><p>Ollama 在电脑上运行模型，并提供 <strong>OpenAI 兼容</strong> 的 HTTP API（默认端口 <code>11434</code>）。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>打开官网 <a href="https://ollama.com/download" target="_blank" rel="noreferrer">https://ollama.com/download</a>，下载 Windows 安装包。</li><li>安装并启动 Ollama（托盘区应出现图标）。</li><li>打开 <strong>命令提示符</strong> 或 <strong>PowerShell</strong>，执行：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>能输出版本号即安装成功。</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><ol><li>从 <a href="https://ollama.com/download" target="_blank" rel="noreferrer">https://ollama.com/download</a> 下载 macOS 版并拖入「应用程序」。</li><li>首次打开允许网络权限。</li><li>打开「终端」：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="验证本机-api" tabindex="-1">验证本机 API <a class="header-anchor" href="#验证本机-api" aria-label="Permalink to &quot;验证本机 API&quot;">​</a></h2><p>服务启动后，在电脑浏览器打开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:11434</span></span></code></pre></div><p>或终端：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:11434/api/tags</span></span></code></pre></div><p>能返回 JSON（模型列表，可能为空）说明 API 已监听。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./models">下载与选择模型</a></li><li><a href="./lan">开启局域网访问</a>（手机连电脑必做）</li></ul>',17)])])}const g=l(s,[["render",n]]);export{m as __pageData,g as default};
